DELETE FROM public.question_keys_private;
DELETE FROM public.questions_public;
ALTER SEQUENCE public.questions_public_id_seq RESTART WITH 1;
SELECT setval('public.questions_public_id_seq', (SELECT max(id) FROM public.questions_public));

CREATE POLICY "question images readable by authenticated"
ON storage.objects FOR SELECT TO authenticated
USING (bucket_id = 'question-images');

CREATE POLICY "question images insert by authenticated"
ON storage.objects FOR INSERT TO authenticated
WITH CHECK (bucket_id = 'question-images');

CREATE POLICY "question images update by authenticated"
ON storage.objects FOR UPDATE TO authenticated
USING (bucket_id = 'question-images')
WITH CHECK (bucket_id = 'question-images');

CREATE POLICY "question images delete by authenticated"
ON storage.objects FOR DELETE TO authenticated
USING (bucket_id = 'question-images');